// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: deployer initializes MinSum = 1 ether
        c.SetMinSum(1 ether);
        c.Initialized();

        // Alice deposits 1 ether
        address alice = address(0x1);
        vm.deal(alice, 1 ether);
        vm.prank(alice);
        c.Deposit{value: 1 ether}();

        // Bob deposits 0.5 ether
        address bob = address(0x2);
        vm.deal(bob, 0.5 ether);
        vm.prank(bob);
        c.Deposit{value: 0.5 ether}();

        // Bob attempts to collect 1.5 ether (more than his balance)
        vm.prank(bob);
        try c.Collect(1.5 ether) {
            // If it didn't revert, the bug is triggered
        } catch {
            // Reference reverts here
        }

        // Check Bob's balance: in reference it should be 0.5 ether (unchanged), in bug it underflows
        assertTrue(c.balances(bob) == 0.5 ether);
    }
}

