// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address user = address(0x123);
        vm.deal(user, 2 ether);
        vm.prank(user);
        c.Deposit{value: 2 ether}();
        // reference: SetMinSum reverts after initialized; bug: succeeds
        c.Initialized();
        // In reference, this call will revert; bug has MinSum = 0 (unchanged)
        // To trigger difference, we rely on the buggy version allowing SetMinSum anytime
        // But we need the buggy version's SetMinSum to actually change MinSum
        // So we call SetMinSum after Initialized (only possible in buggy)
        // Bug: SetMinSum(1) succeeds; reference reverts.
        // We'll test Collect behavior based on MinSum value.
        // For the reference (where SetMinSum reverts), we need MinSum=1 ether for collect to fail
        // For the bug (where SetMinSum succeeds), MinSum becomes 1 (very small)
        // We'll try Collect(1) and catch revert.
        bool ok;
        vm.prank(user);
        try c.Collect(1) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false, "reference should revert, bug succeeds but we cannot call SetMinSum without revert in reference");
        // Actually this doesn't demonstrate the difference correctly. Let's rethink.
        // The difference is that after calling SetMinSum(1) after Initialized, the reference reverts but bug sets MinSum=1.
        // So to witness: call SetMinSum(1) after Initialized, then call Collect(1). In reference, Collect reverts; in bug, Collect succeeds.
        // We'll do a try/catch on SetMinSum first, but we need the actual divergence after Collect.
        // Better: Use a try/catch on the SetMinSum call itself to set a flag, then do Collect based on that.
        // But instruction: End with exactly one assertion reading c's public surface.
        // Simpler: We'll make the collect call and catch, but need the pre-state to be different between reference and bug.
        // The simplest: In the reference, SetMinSum reverts so MinSum stays 1 ether; in bug, SetMinSum(1) sets MinSum=1.
        // Therefore after calling SetMinSum(1) after Initialized:
        // reference: MinSum = 1 ether; bug: MinSum = 1.
        // Then user with balance 2 ether tries Collect(1): reference fails (MinSum>balance? Actually 1e18 < 2e18 so it would succeed! Wait minSum=1 ether, user has 2 ether, so it would succeed! That's wrong.
        // Need condition where MinSum > balance for reference, but < balance for bug.
        // set MinSum to a value greater than user's balance in reference but lower in bug.
        // Reference MinSum=1 ether; bug we set to 1. User deposits 0.5 ether (0.5e18). Then Collect(1) should revert in reference (0.5e18 < 1e18) but succeed in bug (0.5e18 >= 1).
        // So let's do that.
        delete c; // reset
        c = new C();
        vm.deal(user, 0.5 ether);
        vm.prank(user);
        c.Deposit{value: 0.5 ether}();
        // SetMinSum(1) after Initialized - in reference reverts, in bug succeeds.
        // We'll execute SetMinSum inside try/catch:
        bool setOK;
        try c.SetMinSum(1) {
            setOK = true;
        } catch {
            setOK = false;
        }
        // Now call Collect(1) and see if it reverts
        bool collectOK;
        vm.prank(user);
        try c.Collect(1) {
            collectOK = true;
        } catch {
            collectOK = false;
