        // Now call Collect(0.5 ether)
        // In reference: balances[alice] >= MinSum (1 ether >= 0.5) && balances[alice] >= _am (1 >= 0.5) => true
        // Then balances[alice] = 1 - 0.5 = 0.5 ether, and sends 0.5 ether to alice -> success
        // In buggy version: balances[alice] = 1 + 0.5 = 1.5 ether, then sends 0.5 ether to alice -> success
        // So both succeed, but balances differ: 0.5 vs 1.5
        vm.prank(alice);
        c.Collect(0.5 ether);

        // Assert that balance is 0.5 ether (reference behavior)
        // Buggy version would have 1.5 ether, causing this assertion to fail
        assertTrue(c.balances(alice) == 0.5 ether);
    }
}

