pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: avoid initialization reversion
        c.SetMinSum(100);
        c.SetLogFile(address(0x0486cF65A2F2F3A392CBEa398AFB7F5f0B72FF46));
        c.Initialized();

        // Deal ether to two users
        vm.deal(address(0x1), 30 ether);
        vm.deal(address(0x2), 10 ether);

        // Alice deposits 30 ether
        vm.prank(address(0x1));
        c.Deposit{value: 30 ether}();

        // Bob deposits 10 ether
        vm.prank(address(0x2));
        c.Deposit{value: 10 ether}();

        // Alice tries to collect 1 wei (her balance 30 ether < MinSum=100 ether, so condition fails in reference, reverts)
        vm.prank(address(0x1));
        // In the correct contract: Collect reverts because balances[Alice] < MinSum
        // In the buggy contract: condition passes (balances[Alice] >= MinSum false? Wait, check: MinSum=100, Alice balance=30 ether -> false, so condition fails -> also reverts? Need real divergence)
        // Actually: MinSum=100, Alice balance=30 ether -> condition fails in both -> same. Need different state.
        // Let's set MinSum=1 wei.
        // Reset for new setup:
        c = new C();
        c.SetMinSum(1);
        c.SetLogFile(address(0x0486cF65A2F2F3A392CBEa398AFB7F5f0B72FF46));
        c.Initialized();
        vm.deal(address(0x1), 30 ether);
        vm.deal(address(0x2), 10 ether);
        vm.prank(address(0x1));
        c.Deposit{value: 30 ether}();
        vm.prank(address(0x2));
        c.Deposit{value: 10 ether}();

        // Now MinSum=1, Alice's balance=30 ether >=1, so condition passes for both.
        // Alice calls Collect(1 wei). Reference: balance=30 ether - 1 = 29999999999999999999; buggy: balance=30 ether + 1 = 30000000000000000001.
        vm.prank(address(0x1));
        c.Collect{value: 0}(1);

        // Assert: reference balance after Collect is 30 ether - 1, buggy would be 30 ether + 1.
        // Since we called Collect which succeeded (no revert), c.balances(address(0x1)) is different.
        // Reference: 29999999999999999999; buggy: 30000000000000000001.
        // But we don't know which contract we have – we just test the deployed one.
        // For the reference, this assertion passes; for buggy, it fails because balance is larger.
        assertTrue(c.balances(address(0x1)) < 30 ether);
    }
}

